@settings(max_examples=100, suppress_health_check=[HealthCheck.too_slow])
@given(message_strategy)
def test_sha256_digest_length_and_determinism(message):
    """Hash output is 32 bytes and deterministic."""
    digest1 = sha256_digest(message)
    digest2 = sha256_digest(message)
    assert len(digest1) == 32
    assert digest1 == digest2

@given(message_strategy)
def test_sha256_digest_avalanche_effect(message):
    """Flipping one bit changes the digest significantly."""
    if len(message) == 0:
        return  # Cannot flip bit in empty message
    original = sha256_digest(message)
    # Flip the first bit of the message
    mutated = bytearray(message)
    mutated[0] ^= 0x01
    mutated_digest = sha256_digest(bytes(mutated))
    # Count differing bits
    diff_bits = sum(bin(a ^ b).count('1') for a, b in zip(original, mutated_digest))
    # Avalanche: at least 50% of bits should differ (128 out of 256)
    assert diff_bits >= 128

@given(key_strategy, message_strategy)
def test_sign_verify_roundtrip(key, message):
    """Signature generated with key verifies against same key."""
    signature = sign_message(key, message)
    assert verify_signature(key, message, signature) is True

@given(key_strategy, message_strategy)
def test_sign_verify_rejects_tampered_message(key, message):
    """Signature fails against a modified message."""
    if len(message) == 0:
        return
    signature = sign_message(key, message)
    mutated = bytearray(message)
    mutated[0] ^= 0x01
    assert verify_signature(key, bytes(mutated), signature) is False

@given(key_strategy, message_strategy)
def test_sign_verify_rejects_wrong_key(key, message):
    """Signature fails against a different key."""
    other_key = bytes([key[0] ^ 0xFF] + list(key[1:]))
    signature = sign_message(key, message)
    assert verify_signature(other_key, message, signature) is False

